<template>
  <aside class="view-citation" :class="{ 'is-reference': !texts.length, 'is-footer': footer }" :aria-label="`Cited from ${pageLabel}`">
    <blockquote v-if="texts.length">
      <p v-for="(text, index) in texts" :key="`${index}-${text}`">{{ text }}</p>
    </blockquote>
    <button type="button" class="citation-source" @click="$emit('open-source', source)">
      <span class="citation-mark" aria-hidden="true">↳</span>
      <span class="citation-copy">
        <span class="citation-page">Cited from {{ pageLabel }}</span>
        <strong>{{ source.title }}</strong>
      </span>
      <ArrowUpRightIcon class="citation-open" />
    </button>
  </aside>
</template>

<script>
import { sourcePageLabel } from '../../utils/viewSourceTarget';

export default {
  name: 'ViewCitation',
  props: {
    source: { type: Object, required: true },
    texts: { type: Array, default: () => [] },
    footer: { type: Boolean, default: false },
  },
  computed: {
    pageLabel() {
      return sourcePageLabel(this.source);
    },
  },
  emits: ['open-source'],
};
</script>

